window.SAMANDIS_WORK_PAPER_CSS="@font-face{font-family:WorkReportRavi;src:url('/fonts/Ravi-Regular.woff2') format('woff2');font-weight:400;font-display:swap}\n@font-face{font-family:WorkReportRavi;src:url('/fonts/Ravi-Bold.woff2') format('woff2');font-weight:700;font-display:swap}\n.own-report{max-width:1180px;margin:auto}\n.own-report>h1{font-size:25px;margin:0 0 5px;line-height:1.8}\n.own-report>.shared-meta{margin:0 0 24px;line-height:1.9}\n.own-report-toolbar{display:flex;align-items:stretch;gap:16px;flex-wrap:wrap;margin:0 0 28px}\n.desktop-shell .own-report-toolbar .range-controls{flex:1 1 590px;display:flex;align-items:flex-end;justify-content:center;gap:16px;margin:0;padding:20px;background:var(--ui-soft,#edf0f5);border:0;border-radius:24px}\n.own-report-toolbar .range-controls label{font-size:11px;gap:8px}\n.own-report-toolbar .range-controls button{min-height:42px;padding:10px 20px;white-space:nowrap}\n.own-report-actions{display:flex;align-items:center;justify-content:center;gap:10px;margin:0;flex:0 1 auto;padding:14px 0}\n.own-report-actions button{display:flex;align-items:center;justify-content:center;gap:7px;min-height:42px;white-space:nowrap;font-size:11px;padding:10px 17px;border-radius:999px;cursor:pointer}\n.own-report-actions button:disabled{opacity:.45;cursor:wait}\n.own-report-actions .secondary{background:var(--ui-soft,#e9edf3);border:0;color:var(--ui-text,#344d70)}\n.own-report-print-frame{position:fixed;width:1px;height:1px;opacity:0;pointer-events:none;bottom:0;left:0}\n#ownReportBody{min-width:0}\n#myWorkReportNav{display:flex;align-items:center;gap:10px}\n#myWorkReportNav>span:first-child{flex:0 0 18px;font-size:19px}\n#myWorkReportNav>span:last-child{font-size:12px;flex:1;text-align:right}\n.work-report-export{margin:0;background:#fff;direction:rtl}\n.own-report-paper{font-family:WorkReportRavi,Tahoma,sans-serif!important;box-sizing:border-box;width:210mm;max-width:100%;min-height:297mm;margin:0 auto;padding:14mm 13mm 11mm;background:#fff;color:#25354d;border:0;border-radius:14px;font-size:12px;line-height:1.9;box-shadow:0 10px 40px #1b2b4310;direction:rtl}\n.own-report-paper *{box-sizing:border-box}\n.own-report-paper .brief-report-header{display:flex;flex-direction:column;gap:26px;position:relative!important;inset:auto!important;height:auto!important;min-height:0!important;max-height:none!important;overflow:visible;padding:0 0 24px!important;margin:0!important;background:#fff!important;border:0;border-bottom:2px solid #25275c;box-shadow:none!important}\n.brief-report-header:after{content:'';position:absolute;bottom:-2px;right:0;width:60px;height:2px;background:#cdb278}\n.brief-company{display:flex;align-items:center;gap:10px;align-self:flex-start}\n.brief-company img{display:block;width:48px;height:48px;object-fit:contain}\n.brief-company span{font-size:12px;font-weight:700;color:#25275c}\n.own-report-paper .brief-heading{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,2fr) minmax(0,1fr);align-items:center;gap:14px;width:100%;padding:0}\n.own-report-paper .brief-heading>*{position:static!important;transform:none!important;min-width:0;overflow-wrap:anywhere;margin:0;line-height:1.9}\n.own-report-paper .brief-heading p{font-size:11px;text-align:right;color:#697386}\n.own-report-paper .brief-heading h1{font-size:21px;font-weight:700;text-align:center;color:#25275c}\n.own-report-paper .brief-heading h2{font-size:12px;font-weight:700;text-align:left;color:#39465b}\n.brief-period{display:flex;align-items:center;justify-content:space-between;gap:20px;margin:24px 0 30px;padding:14px 18px;border:0;background:#f3f4f7;border-radius:10px}\n.brief-period>div{display:flex;flex-direction:column;gap:4px}\n.brief-period>div:last-child{text-align:left}\n.brief-period span{font-size:9px;color:#7c8494}\n.brief-period b{font-size:11px;font-weight:400;color:#39465b}\n.own-report-paper .brief-table{width:100%;border-collapse:collapse;table-layout:fixed;margin:0}\n.own-report-paper .brief-table th{background:#ecedf3;color:#394364;border:0;padding:12px 16px;text-align:right;font-size:10px;font-weight:700;line-height:1.9}\n.brief-table th:first-child{border-radius:0 8px 8px 0}\n.brief-table th:last-child{border-radius:8px 0 0 8px}\n.own-report-paper .brief-table td{padding:18px 16px;vertical-align:top;overflow-wrap:anywhere;border:0;border-bottom:1px solid #eceef2;font-size:11px;line-height:2.1;text-align:right;background:#fff}\n.brief-table tbody tr:nth-child(even) td{background:#f8f9fb}\n.own-report-paper .brief-table .brief-date{color:#46536b;background:#f4f5f8}\n.brief-date b{display:block;font-size:11px;font-weight:700;line-height:2}\n.brief-date small{display:block;font-size:9px;color:#8a91a0;margin-top:4px}\n.brief-table ul{list-style:none;padding:0;margin:0}\n.brief-table li{position:relative;padding:0 12px 0 0;margin:0 0 10px;line-height:2.1;color:#39465b}\n.brief-table li:last-child{margin-bottom:0}\n.brief-table li:before{content:'';position:absolute;right:0;top:10px;width:4px;height:4px;border-radius:50%;background:#baa36b}\n.own-report-paper .brief-table td.brief-empty{text-align:center;color:#8a91a0;padding:38px 16px}\n.brief-footer{display:flex;justify-content:space-between;gap:16px;margin-top:28px;padding-top:12px;border-top:1px solid #e8ebf1;color:#8a91a0;font-size:8px}\n.work-report-export .own-report-paper{border-radius:0;box-shadow:none}\n@page{size:A4;margin:12mm}\n@media print{html,body{margin:0!important;padding:0!important}.own-report-paper{width:100%;max-width:none;min-height:0;margin:0;padding:0;border:0;border-radius:0;box-shadow:none}.brief-report-header,.brief-period,.brief-footer{break-inside:avoid}.brief-table thead{display:table-header-group}.brief-table tr{break-inside:avoid}.brief-table th,.brief-table td,.brief-period{print-color-adjust:exact;-webkit-print-color-adjust:exact}}\n@media screen and (max-width:700px){.own-report-toolbar{gap:10px;margin-bottom:20px}.desktop-shell .own-report-toolbar .range-controls{padding:16px;gap:12px}.own-report-actions{width:100%;padding:0;justify-content:flex-end}.own-report-paper{padding:24px 18px;min-height:0;border-radius:12px}.own-report-paper .brief-report-header{gap:20px;padding-bottom:18px!important}.brief-company img{width:40px;height:40px}.own-report-paper .brief-heading{gap:8px;grid-template-columns:minmax(0,1fr) minmax(0,1.8fr) minmax(0,1fr)}.own-report-paper .brief-heading h1{font-size:15px}.own-report-paper .brief-heading h2,.own-report-paper .brief-heading p{font-size:10px}.brief-period{padding:12px;gap:12px;margin:18px 0 22px}.brief-period b{font-size:10px}.own-report-paper .brief-table td,.own-report-paper .brief-table th{padding:12px 9px;font-size:10px}.brief-date b{font-size:10px}.brief-footer{font-size:7px;gap:10px}}\n";
